    if ($18 == "True") fraud[m] += $9;
} END {
    for (i=1; i<=12; i++) {
        if (total[i] > 0) print "Month", i, "Rate:", fraud[i]/total[i], "Total:", total[i];
    }
}' /data/payments.csv

